namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var allocations = new List<string>();
        var remaining = item.OnHand - item.Reserved;

        foreach (var zone in warehouse.Zones)
        {
            if (remaining <= 0)
                break;
            if (!CanAllocateTo(zone))
                continue;

            var quantity = CalculatePlacement(remaining, zone.Capacity);
            if (quantity <= 0)
                continue;

            allocations.Add($"{zone.Name}:{quantity}");
            remaining -= quantity;
        }

        if (remaining > 0)
            allocations.Add($"OVERFLOW:{remaining}");

        return allocations;
    }

    private static bool CanAllocateTo(WarehouseZone zone) =>
        zone.Capacity > 0 && !string.IsNullOrEmpty(zone.Name);

    private static int CalculatePlacement(int remaining, int capacity) =>
        remaining > capacity ? capacity :
        remaining > capacity / 2 ? remaining - 1 :
        remaining;
}
